///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.MM_swapImgRestore
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.MM_swapImgRestore = function () {
    /* sdd-asis-lifecycle:begin MM_swapImgRestore — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    let i, x, a = (document.MM_sr || { elements: [] });
    for (i = 0; a && i < a.length && (x = a[i]) && x.oSrc; i++) {
        x.src = x.oSrc;
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.MM_swapImage
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.MM_swapImage = function () {
    /* sdd-asis-lifecycle:begin MM_swapImage — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    let i, j = 0, x, a = scwin.MM_swapImage.arguments;
    document.MM_sr = new Array();
    for (i = 0; i < (a.length - 2); i += 3) {
        if ((x = MM_findObj(a[i])) != null) {
            (document.MM_sr || { elements: [] })[j++] = x;
            if (!x.oSrc) {
                x.oSrc = x.src;
            }
            x.src = a[i+2];
        }
    }
    /* sdd-asis-lifecycle:end */
};
